    from: number,
    to: number,
    easing: string,
    curve: EasingFn | null,
    seek?: number,
  ): Axis => {
    const anim = element.animate(
      [{ [property]: `${from}px` }, { [property]: `${to}px` }],
      { duration, easing, fill: "both" },
    );
    if (seek !== undefined) anim.currentTime = seek;
    return { anim, from, to, easing, curve, startedAt: now() - (seek ?? 0) };
